const Deadline = ({date}) => {
  const d=daysDiff(date); if(d===null)return null;
  const col=d<0?"#ef4444":d<=3?"#f97316":d<=7?"#eab308":"#475569";
  const lbl=d<0?`${Math.abs(d)}d overdue`:d===0?"Today!":d===1?"Tomorrow":`${d}d left`;
