  // ÔöÇÔöÇ Gmail Scanner ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  async function startGmailScan() { setGmailLoading(true); setTimeout(() => { setGmailLoading(false); setGmailStatus({msg:"MCP Gmail module disconnected.",type:"error"}); }, 500); }

  // ÔöÇÔöÇ Excel ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  function exportXLSX() {
    const rows = jobs.map(j=>({"Job Title":j.title,"Company":j.company,"Location":j.location,"Type":j.type,"Salary":j.salary,"Skills":j.skills,"Source":j.source,"Apply Link":j.applyLink,"Status":j.status,"Priority":j.priority,"Applied Date":j.appliedDate,"Deadline":j.deadline,"Notes":j.notes}));
    const ws = XLSX.utils.json_to_sheet(rows);
    ws["!cols"]=[{wch:35},{wch:20},{wch:22},{wch:13},{wch:14},{wch:30},{wch:14},{wch:40},{wch:20},{wch:10},{wch:14},{wch:14},{wch:50}];
    const ws2 = XLSX.utils.json_to_sheet([...STATUS.map(s=>({Status:s,Count:jobs.filter(j=>j.status===s).length})),{Status:"TOTAL",Count:jobs.length}]);
    ws2["!cols"]=[{wch:22},{wch:10}];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb,ws,"Applications");
    XLSX.utils.book_append_sheet(wb,ws2,"Summary");
    XLSX.writeFile(wb,"JobBoard_Pro.xlsx");
    notify("Excel downloaded Ô£ô");
  }
  function importXLSX(e) {
    const file=e.target.files[0]; if(!file)return;
    const reader=new FileReader();
    reader.onload=ev=>{
      try {
        const wb=XLSX.read(ev.target.result,{type:"array"});
        const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        const mapped=rows.map((r)=>({title:r["Job Title"]||r.title||"Untitled",company:r.Company||r.company||"",location:r.Location||r.location||"",type:r.Type||r.type||"Full-time",salary:r.Salary||r.salary||"",skills:r.Skills||r.skills||"",source:r.Source||r.source||"Import",applyLink:r["Apply Link"]||r.applyLink||"",status:r.Status||r.status||"Bookmarked",priority:r.Priority||r.priority||"Medium",appliedDate:r["Applied Date"]||r.appliedDate||"",deadline:r.Deadline||r.deadline||"",notes:r.Notes||r.notes||"",user_id:session.user.id}));
        supabase.from('jobs').insert(mapped).then(({error})=>{ if(!error){ fetchJobs(); notify("Imported Excel Data Ô£ô"); }else notify(error.message, "err"); });
      } catch { notify("Import failed ÔÇö check file format","err"); }
    };
    reader.readAsArrayBuffer(file); e.target.value="";
  }

  // ÔöÇÔöÇ Stats ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const stats = STATUS.reduce((a,s)=>{a[s]=jobs.filter(j=>j.status===s).length;return a},{});
  const overdue = jobs.filter(j=>j.deadline&&daysDiff(j.deadline)<0&&!["Rejected","Withdrawn","Offer"].includes(j.status)).length;
  const soonDue = jobs.filter(j=>j.deadline&&daysDiff(j.deadline)>=0&&daysDiff(j.deadline)<=7&&!["Rejected","Withdrawn","Offer"].includes(j.status)).length;

