              <ResponsiveContainer width="100%" height={180}>
                <BarChart data={STATUS.map(s=>({name:s.slice(0,6),val:stats[s]}))} margin={{left:-24}}>
                  <XAxis dataKey="name" tick={{fill:"#1e293b",fontSize:9}} axisLine={false} tickLine={false}/>
